export const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
]

// Curated set of world-famous "iconic" trails, surfaced by the Iconic filter.
// Kept as a list of trail_ids so the trail records stay untouched.
export const ICONIC_TRAIL_IDS = new Set([
  1, 5, 9, 13, 23, // Australia: Wineglass Bay, Kings Canyon, Dove Lake, Wilpena/St Mary, Mt Oberon
  2, 6, 8, 15, 16, // New Zealand: Tongariro, Roys Peak, Hooker Valley, Abel Tasman, Milford
  25, 27, 30, 42, 45, 46, 31, // Japan: Fuji, Fushimi Inari, Kumano Kodō, Yarigatake, Kitadake, Jōmon Sugi, Takao
  65, 68, 71, 74, 72, // Malaysia: Kinabalu, Taman Negara (Bukit Teresek), Gunung Ledang, Mulu Pinnacles, Gunung Tahan
  107, 108, 111, 112, 124, // Thailand: Doi Luang Chiang Dao, Phu Kradueng, Mokoju, Kew Mae Pan, Phu Chi Fa
  139, 141, 143, 142, 147, // South Korea: Ulsanbawi (Seoraksan), Hallasan, Jirisan Cheonwangbong, Jeju Olle, Seongsan Ilchulbong
  160, 162, 166, // South Korea (v3): Dinosaur Ridge (Seoraksan), Jirisan main-ridge traverse, Naejangsan nine-peaks
  173, 181, 182, 183, 187, 188, 193, // Taiwan: Syakaro, Dabajianshan, North Dawu, Jiaming Lake, Hehuan Jianshan, Hehuanshan East, Alishan Giant Trees
  196, 197, 198, 200, 203, 207, // Taiwan (NP): Yushan, Xueshan, Holy Ridge, Qilai, Zhuilu Old Trail, Elephant Mountain
  209, 210, 211, // Nepal: Annapurna Circuit, Annapurna Base Camp, Everest Base Camp
  215, 216, 217, // South America: Torres del Paine W Trek, O Circuit, Aconcagua
])

export function isIconic(trail) {
  return ICONIC_TRAIL_IDS.has(trail.trail_id)
}

// Invariant: every iconic trail MUST have at least one image. Iconic trails are
// surfaced prominently (the "Iconic" filter, larger cards), so a missing hero
// image is an immediately visible bug. This guard fails fast in dev/build if a
// new iconic trail is added without a `photo_url`.
export const iconicTrailsMissingImage = trails.filter(
  (t) => ICONIC_TRAIL_IDS.has(t.trail_id) && !(t.photo_url && t.photo_url.trim()),
)
if (iconicTrailsMissingImage.length > 0 && import.meta.env?.DEV) {
  throw new Error(
    `Iconic trails must have at least one image; missing photo_url for trail_id(s): ${iconicTrailsMissingImage
      .map((t) => t.trail_id)
      .join(', ')}`,
  )
}

// Trails that are only OPEN/accessible part of the year (snow-blocked alpine,
// seasonal roads, permit windows). Value is the open window [startMonth, endMonth]
// (wrap-aware). Everything NOT listed here is open year-round — the seasonal
// highlight bars just mark the *best* months, not the only ones you can visit.
export const SEASONAL_ACCESS = {
  25: [7, 9], 26: [4, 11], 32: [6, 10], 36: [4, 11], 37: [4, 11], // Japan
  42: [7, 9], 43: [7, 10], 44: [4, 11], 45: [6, 11], 48: [5, 10],
  50: [5, 11], 52: [5, 10], 54: [6, 10], 56: [5, 11], 57: [7, 10],
  58: [6, 10], 61: [4, 11], 63: [4, 11], 64: [7, 9],
  16: [10, 4], // New Zealand — Milford Track (Great Walk season)
  88: [7, 9], 89: [6, 9], 91: [6, 9], 92: [5, 10], 94: [7, 9], // Iceland
  103: [5, 9], 104: [7, 9], 105: [6, 9],
  // Thailand — open/close windows updated 2026-07-10 from the curated
  // thailand_hiking_trails_v4 CSV (per-park "ช่วงเวลาเปิด-ปิด" column).
  // Most northern & western summit treks run the cool/dry season only.
  // Notable exceptions: Phu Kradueng (Oct–May) and Kew Mae Pan (Nov–May) keep
  // road-served access later; Phu Soi Dao (Jul–Jan) runs THROUGH the rains;
  // Khao Luang Sukhothai (May–Feb) closes annually 1 Mar–30 Apr; Pae Toh Lo Su
  // (Jun–Oct) is a RAINY-season trek; Khao Jet Yod (Feb–Apr) avoids the
  // southern monsoon. Pha Hin Kub runs weekend-only treks year-round (not
  // month-gated here); Doi Pha Hom Pok and Ang Ka are open year-round.
  107: [11, 2], 108: [10, 5], 109: [11, 1], 110: [7, 1], 111: [11, 2],
  112: [11, 5], 114: [11, 2], 115: [5, 2], 116: [6, 2], 118: [10, 2],
  119: [6, 10], 120: [11, 2], 121: [10, 5], 126: [10, 2], 127: [10, 3],
  128: [9, 2], 129: [10, 2], 130: [11, 2], 131: [9, 1], 132: [2, 4],
  133: [11, 2], 134: [10, 2], 135: [10, 2], 136: [11, 2], 137: [11, 2],
  172: [5, 2], // Doi Khun Tan — closes annually 1 Mar–30 Apr
  // South America, from the park authorities' own closure notices (2026-07-30):
  // CONAF closes the Sendero W in June and July, and the Macizo Paine (O)
  // circuit from May until 31 October. Aconcagua's season is 15 Nov – 31 Mar.
  215: [8, 5], 216: [11, 4], 217: [11, 3],
}

export function isYearRound(trail) {
  return !(trail.trail_id in SEASONAL_ACCESS)
}

// True when a seasonally-gated trail is shut in `month` (1-12, defaulting to
// the real current month). This is separate from `status`, which records only
// exceptional closures (landslides, earthquakes, volcanic gas) — a trail can
// sit at status 'Open' all year and still be closed today because its access
// window has ended, so anything showing the status must consult this too.
export function isOutOfSeason(trail, month = new Date().getMonth() + 1) {
  const window = SEASONAL_ACCESS[trail.trail_id]
  return window ? !monthInRange(month, window[0], window[1]) : false
}

// Set of months (1-12) the trail is open/accessible.
export function openMonths(trail) {
  const months = new Set()
  const window = SEASONAL_ACCESS[trail.trail_id]
  for (let m = 1; m <= 12; m++) {
    if (!window || monthInRange(m, window[0], window[1])) months.add(m)
  }
  return months
}

// Short label for the open window, e.g. 'Jul–Sep' (or null when year-round).
export function openRangeLabel(trail) {
  const window = SEASONAL_ACCESS[trail.trail_id]
  if (!window) return null
  const abbr = (m) => MONTH_NAMES[m - 1].slice(0, 3)
  return window[0] === window[1] ? abbr(window[0]) : `${abbr(window[0])}–${abbr(window[1])}`
}

export function isTrailInMonth(trail, month) {
  return trail.seasonal_highlights.some((h) => monthInRange(month, h.month_start, h.month_end))
}

export function highlightsForMonth(trail, month) {
  return trail.seasonal_highlights.filter((h) => monthInRange(month, h.month_start, h.month_end))
}

function monthInRange(month, start, end) {
  if (start <= end) return month >= start && month <= end
  // wraps around year end, e.g. Nov(11)–Feb(2)
  return month >= start || month <= end
}
